-- TB_MEMBER Table
CREATE TABLE IF NOT EXISTS "TB_MEMBER" (
    "USERNAME" VARCHAR(255) PRIMARY KEY,
    "NAME" VARCHAR(255),
    "PASSWORD" VARCHAR(255),
    "PHONE" VARCHAR(255),
    "EMAIL" VARCHAR(255),
    "BIRTH" DATE
);

-- TB_PROFILE Table
CREATE TABLE IF NOT EXISTS "TB_PROFILE" (
    "FILE_NUM" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "FILE_NAME" VARCHAR(255),
    "ORI_NAME" VARCHAR(255),
    "USERNAME" VARCHAR(255)
);

-- TB_PRODUCT Table
CREATE TABLE IF NOT EXISTS "TB_PRODUCT" (
    "PRODUCT_NUM" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "PRODUCT_NAME" VARCHAR(255),
    "PRODUCT_CONTENTS" TEXT,
    "PRODUCT_TYPE" VARCHAR(255),
    "PRODUCT_RATE" DOUBLE
);

-- TB_PRODUCTFILE Table
CREATE TABLE IF NOT EXISTS "TB_PRODUCTFILE" (
    "FILE_NUM" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "FILE_NAME" VARCHAR(255),
    "ORI_NAME" VARCHAR(255),
    "PRODUCT_NUM" BIGINT
);

-- TB_NOTICE Table
CREATE TABLE IF NOT EXISTS "TB_NOTICE" (
    "BOARD_NUM" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "BOARD_TITLE" VARCHAR(255),
    "BOARD_WRITER" VARCHAR(255),
    "BOARD_CONTENTS" TEXT,
    "BOARD_DATE" TIMESTAMP,
    "BOARD_HIT" BIGINT
);

-- TB_NOTICEFILE Table
CREATE TABLE IF NOT EXISTS "TB_NOTICEFILE" (
    "FILE_NUM" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "FILE_NAME" VARCHAR(255),
    "ORI_NAME" VARCHAR(255),
    "BOARD_NUM" BIGINT
);

-- TB_QNA Table
CREATE TABLE IF NOT EXISTS "TB_QNA" (
    "BOARD_NUM" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "BOARD_TITLE" VARCHAR(255),
    "BOARD_WRITER" VARCHAR(255),
    "BOARD_CONTENTS" TEXT,
    "BOARD_DATE" TIMESTAMP,
    "BOARD_HIT" BIGINT,
    "BOARD_REF" BIGINT,
    "BOARD_STEP" BIGINT,
    "BOARD_DEPTH" BIGINT
);

-- TB_QNAFILE Table
CREATE TABLE IF NOT EXISTS "TB_QNAFILE" (
    "FILE_NUM" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "FILE_NAME" VARCHAR(255),
    "ORI_NAME" VARCHAR(255),
    "BOARD_NUM" BIGINT
);

-- TB_REVIEW Table
CREATE TABLE IF NOT EXISTS "TB_REVIEW" (
    "REVIEW_NUM" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "USERNAME" VARCHAR(255),
    "REVIEW_CONTENTS" TEXT,
    "REVIEW_STAR" INT,
    "REVIEW_DATE" TIMESTAMP,
    "PRODUCT_NUM" BIGINT
);

-- TB_CART Table
CREATE TABLE IF NOT EXISTS "TB_CART" (
    "USERNAME" VARCHAR(255),
    "PRODUCT_NUM" BIGINT,
    PRIMARY KEY ("USERNAME", "PRODUCT_NUM")
);

-- TB_ACCOUNT Table
CREATE TABLE IF NOT EXISTS "TB_ACCOUNT" (
    "ACCOUNTNUM" VARCHAR(255) PRIMARY KEY,
    "USERNAME" VARCHAR(255),
    "PRODUCTNUM" BIGINT,
    "ACCOUNTPW" VARCHAR(255),
    "ACCOUNTBALANCE" BIGINT,
    "ACCOUNTDATE" TIMESTAMP
);
